
.contact {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-family: var(--font-readout);
  font-size: 12px;
}

.contact__empty {
  color: var(--c-text-muted);
}

.contact__row {
  display: grid;
  grid-template-columns: 5.4em 1fr 2.2em;
  align-items: center;
  gap: 8px;
}

.contact__name {
  color: var(--c-text-muted);
}

.contact__track {
  display: flex;
  gap: 2px;
  height: 7px;
}

.contact__cell {
  flex: 1;
  background: #20252b;
}

.contact__cell--on {
  background: var(--c-primary);
}

.contact__value {
  text-align: right;
  color: var(--c-text-muted);
  font-variant-numeric: tabular-nums;
}
