
.console {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  box-shadow: inset 0 0 0 1px #0f1113;
  font-family: var(--font-body);
  overflow: hidden;
}

.gauges {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 10px 12px;
}

.points {
  display: flex;
  gap: 16px;
  padding: 0 12px 9px;
}

.alert {
  padding: 6px 12px;
  border-top: 1px solid var(--c-danger);
  background: #2a1c1b;
  color: var(--c-danger);
  font-family: var(--font-readout);
  font-size: 12px;
  letter-spacing: 0.08em;
}
