
.standing {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-family: var(--font-readout);
  font-size: 12px;
}

.standing__empty {
  color: var(--c-text-muted);
}

.standing__row {
  display: grid;
  grid-template-columns: 5.4em 1fr 2.6em;
  align-items: center;
  gap: 8px;
}

.standing__name {
  color: var(--c-text-muted);
}

.standing__track {
  position: relative;
  height: 8px;
  background: #14171a;
  border: 1px solid var(--c-border);
}

.standing__axis {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 1px;
  background: #4a545f;
}

.standing__fill {
  position: absolute;
  top: 0;
  bottom: 0;
}

.standing__fill--positive {
  background: var(--c-calm);
}

.standing__fill--negative {
  background: var(--c-hostile);
}

.standing__fill--flat {
  background: var(--c-text-muted);
}

.standing__value {
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: var(--c-text);
}

.standing__value--positive {
  color: var(--c-calm);
}

.standing__value--negative {
  color: var(--c-hostile);
}
