
.cargo {
  display: flex;
  flex-direction: column;
  gap: 3px;
  font-family: var(--font-readout);
  font-size: 12px;
}

.cargo__empty {
  color: var(--c-text-muted);
}

.cargo__row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 10px;
  padding-bottom: 3px;
  border-bottom: 1px dotted var(--c-border);
}

.cargo__name {
  color: var(--c-text);
}

.cargo__count {
  color: var(--c-text-muted);
  font-variant-numeric: tabular-nums;
}

.cargo__value {
  min-width: 5.4em;
  text-align: right;
  color: var(--c-primary);
  font-variant-numeric: tabular-nums;
}
